mapper.select:
select *,ca.name as category_name from setmeal st
    left join category ca on st.category_id = ca.id

    
        and st.name like concat('%',#{name},'%')
    
    
        and st.category_id = #{categoryId}
    
    
        and st.status = #{status}
    

order by st.create_time desc

mapper.update:
update setmeal
category_id = #{categoryId}, name = #{name}, price = #{price}, status = #{status}, description = #{description}, image = #{image}, create_time = #{createTime}, update_time = #{updateTime}, create_user = #{createUser}, update_user = #{updateUser},
where id = #{id};
